function(container, apiUrl, tables) {
  // データ取得と初期化
  async function initDashboard() {
    try {
      const projects = await window.aivicApi.list(0) || tables[0]?.records || [];

      // KPI計算
      const totalProjects = projects.length;
      const activeProjects = projects.filter(p => p.status === '進行中' || p.status === '開発中').length;
      const completedProjects = projects.filter(p => p.status === '完了' || p.status === 'リリース済み').length;
      const pendingTasks = projects.filter(p => p.priority === '高' && p.status !== '完了').length;

      // KPI表示更新
      container.querySelector('#kpi-total').textContent = totalProjects;
      container.querySelector('#kpi-active').textContent = activeProjects;
      container.querySelector('#kpi-completed').textContent = completedProjects;
      container.querySelector('#kpi-pending').textContent = pendingTasks;

      // チャート描画
      renderProgressChart(projects);
      renderStatusChart(projects);

      // 要対応項目表示
      renderUrgentTasks(projects);

      // 最新更新表示
      renderRecentUpdates(projects);

    } catch (error) {
      console.error('Dashboard initialization failed:', error);
    }
  }

  // プロジェクト進捗チャート
  function renderProgressChart(projects) {
    const ctx = container.querySelector('#progress-chart').getContext('2d');

    // 月別集計
    const monthlyData = {};
    projects.forEach(project => {
      if (project.created_at || project.start_date) {
        const date = project.created_at || project.start_date;
        const month = date.slice(0, 7); // YYYY-MM
        monthlyData[month] = (monthlyData[month] || 0) + 1;
      }
    });

    const sortedMonths = Object.keys(monthlyData).sort();
    const labels = sortedMonths.map(m => {
      const [year, month] = m.split('-');
      return `${year}/${month}`;
    });
    const data = sortedMonths.map(m => monthlyData[m]);

    new Chart(ctx, {
      type: 'line',
      data: {
        labels: labels,
        datasets: [{
          label: '新規プロジェクト',
          data: data,
          borderColor: '#3b82f6',
          backgroundColor: 'rgba(59, 130, 246, 0.1)',
          tension: 0.4,
          fill: true
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            display: false
          }
        },
        scales: {
          y: {
            beginAtZero: true,
            grid: {
              color: 'rgba(255, 255, 255, 0.1)'
            },
            ticks: {
              color: '#9fb0d1'
            }
          },
          x: {
            grid: {
              color: 'rgba(255, 255, 255, 0.1)'
            },
            ticks: {
              color: '#9fb0d1'
            }
          }
        }
      }
    });
  }

  // ステータス分布チャート
  function renderStatusChart(projects) {
    const ctx = container.querySelector('#status-chart').getContext('2d');

    const statusCount = {};
    projects.forEach(project => {
      const status = project.status || '未設定';
      statusCount[status] = (statusCount[status] || 0) + 1;
    });

    const labels = Object.keys(statusCount);
    const data = Object.values(statusCount);
    const colors = ['#3b82f6', '#22c55e', '#f59e0b', '#ef4444', '#8b5cf6'];

    new Chart(ctx, {
      type: 'doughnut',
      data: {
        labels: labels,
        datasets: [{
          data: data,
          backgroundColor: colors.slice(0, labels.length),
          borderWidth: 0
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            position: 'bottom',
            labels: {
              color: '#9fb0d1',
              font: {
                size: 12
              },
              padding: 8
            }
          }
        }
      }
    });
  }

  // 要対応項目表示
  function renderUrgentTasks(projects) {
    const urgentTasks = projects
      .filter(p => p.priority === '高' && p.status !== '完了')
      .slice(0, 5);

    const html = urgentTasks.length > 0 
      ? urgentTasks.map(task => `
          <div style="padding: 8px 0; border-bottom: 1px solid var(--border); cursor: pointer;" 
               onclick="window.showScreen('scr-3')">
            <div style="font-size: 14px; color: var(--text); margin-bottom: 2px;">${task.name || task.title || 'プロジェクト'}</div>
            <div style="font-size: 12px; color: var(--text-muted);">
              <span style="color: #f59e0b;">●</span> ${task.status || '未設定'}
            </div>
          </div>
        `).join('')
      : '<div style="color: var(--text-muted); font-size: 14px; text-align: center; padding: 20px;">要対応項目はありません</div>';

    container.querySelector('#urgent-tasks').innerHTML = html;
  }

  // 最新更新表示
  function renderRecentUpdates(projects) {
    const recentProjects = projects
      .sort((a, b) => {
        const dateA = a.updated_at || a.created_at || '1970-01-01';
        const dateB = b.updated_at || b.created_at || '1970-01-01';
        return dateB.localeCompare(dateA);
      })
      .slice(0, 4);

    const html = recentProjects.length > 0
      ? recentProjects.map(project => {
          const date = project.updated_at || project.created_at || '';
          const displayDate = date ? date.slice(5, 10).replace('-', '/') : '';
          return `
            <div style="padding: 8px 0; border-bottom: 1px solid var(--border); cursor: pointer;"
                 onclick="window.showScreen('scr-3')">
              <div style="font-size: 14px; color: var(--text); margin-bottom: 2px;">${project.name || project.title || 'プロジェクト'}</div>
              <div style="font-size: 12px; color: var(--text-muted);">${displayDate}</div>
            </div>
          `;
        }).join('')
      : '<div style="color: var(--text-muted); font-size: 14px; text-align: center; padding: 20px;">更新履歴がありません</div>';

    container.querySelector('#recent-updates').innerHTML = html;
  }

  // 初期化実行
  initDashboard();
}

function(container, apiUrl, tables) {
  let currentData = [];
  let filteredData = [];
  let currentPage = 1;
  let itemsPerPage = 20;

  // ステータスバッジのスタイル
  function getStatusBadge(status) {
    const styles = {
      '企画中': 'background: rgba(59, 130, 246, 0.15); color: #3b82f6; border: 1px solid rgba(59, 130, 246, 0.3);',
      '開発中': 'background: rgba(245, 158, 11, 0.15); color: #f59e0b; border: 1px solid rgba(245, 158, 11, 0.3);',
      'テスト中': 'background: rgba(168, 85, 247, 0.15); color: #a855f7; border: 1px solid rgba(168, 85, 247, 0.3);',
      'リリース済み': 'background: rgba(34, 197, 94, 0.15); color: #22c55e; border: 1px solid rgba(34, 197, 94, 0.3);',
      '保守運用': 'background: rgba(107, 114, 128, 0.15); color: #6b7280; border: 1px solid rgba(107, 114, 128, 0.3);'
    };
    const style = styles[status] || styles['企画中'];
    return `<span class="px-2 py-1 text-xs rounded-full" style="${style}">${status || '-'}</span>`;
  }

  // 優先度バッジのスタイル
  function getPriorityBadge(priority) {
    const styles = {
      '高': 'background: rgba(239, 68, 68, 0.15); color: #ef4444; border: 1px solid rgba(239, 68, 68, 0.3);',
      '中': 'background: rgba(245, 158, 11, 0.15); color: #f59e0b; border: 1px solid rgba(245, 158, 11, 0.3);',
      '低': 'background: rgba(107, 114, 128, 0.15); color: #6b7280; border: 1px solid rgba(107, 114, 128, 0.3);'
    };
    const style = styles[priority] || styles['中'];
    return `<span class="px-2 py-1 text-xs rounded-full" style="${style}">${priority || '-'}</span>`;
  }

  // 進捗バーの生成
  function getProgressBar(progress) {
    const percent = Math.min(100, Math.max(0, progress || 0));
    const color = percent >= 80 ? '#22c55e' : percent >= 50 ? '#f59e0b' : '#ef4444';
    return `
      <div class="w-full bg-gray-200 rounded-full h-2" style="background: rgba(255,255,255,0.1);">
        <div class="h-2 rounded-full" style="width: ${percent}%; background: ${color};"></div>
      </div>
      <span class="text-xs mt-1" style="color: var(--text-muted);">${percent}%</span>
    `;
  }

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#project-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="8" class="px-4 py-8 text-center" style="color: var(--text-muted);">
            データがありません
          </td>
        </tr>
      `;
      return;
    }

    tbody.innerHTML = rows.map(row => `
      <tr data-id="${row.id}" class="border-b cursor-pointer hover:bg-opacity-50" 
          style="border-color: rgba(255,255,255,0.08);" 
          onmouseover="this.style.background='rgba(255,255,255,0.05)'" 
          onmouseout="this.style.background='transparent'">
        <td class="px-4 py-3">
          <div>
            <div class="font-medium text-sm" style="color: var(--text);">${row.project_name || row.name || '-'}</div>
            <div class="text-xs" style="color: var(--text-muted);">${row.description || ''}</div>
          </div>
        </td>
        <td class="px-4 py-3">${getStatusBadge(row.status)}</td>
        <td class="px-4 py-3">${getPriorityBadge(row.priority)}</td>
        <td class="px-4 py-3">
          <div class="text-sm" style="color: var(--text);">${row.assignee || row.担当者 || '-'}</div>
        </td>
        <td class="px-4 py-3">
          <div class="w-20">
            ${getProgressBar(row.progress || row.進捗率)}
          </div>
        </td>
        <td class="px-4 py-3">
          <div class="text-sm" style="color: var(--text);">${row.start_date || row.開始日 || '-'}</div>
        </td>
        <td class="px-4 py-3">
          <div class="text-sm" style="color: var(--text);">${row.end_date || row.終了予定日 || '-'}</div>
        </td>
        <td class="px-4 py-3 text-center">
          <div class="flex items-center justify-center gap-2">
            <button class="action-btn secondary edit-btn text-xs px-2 py-1" 
                    data-id="${row.id}"
                    style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); border-radius: 4px;">
              編集
            </button>
            <button class="action-btn secondary delete-btn text-xs px-2 py-1" 
                    data-id="${row.id}"
                    style="background: transparent; color: #ef4444; border: 1px solid rgba(239, 68, 68, 0.3); border-radius: 4px;">
              削除
            </button>
          </div>
        </td>
      </tr>
    `).join('');

    // 結果件数の更新
    container.querySelector('#result-count').textContent = rows.length;
  }

  // 統計情報の更新
  function updateStats(data) {
    const stats = {
      planning: data.filter(r => r.status === '企画中').length,
      developing: data.filter(r => r.status === '開発中').length,
      released: data.filter(r => r.status === 'リリース済み').length
    };

    container.querySelector('#stat-planning').textContent = stats.planning;
    container.querySelector('#stat-developing').textContent = stats.developing;
    container.querySelector('#stat-released').textContent = stats.released;
  }

  // フィルタリング処理
  function applyFilters() {
    const keyword = container.querySelector('#input-search').value.toLowerCase();
    const status = container.querySelector('#status-filter').value;
    const priority = container.querySelector('#priority-filter').value;
    const assignee = container.querySelector('#assignee-filter').value;

    filteredData = currentData.filter(row => {
      const matchKeyword = !keyword || 
        (row.project_name || row.name || '').toLowerCase().includes(keyword) ||
        (row.description || '').toLowerCase().includes(keyword);

      const matchStatus = !status || row.status === status;
      const matchPriority = !priority || row.priority === priority;
      const matchAssignee = !assignee || (row.assignee || row.担当者) === assignee;

      return matchKeyword && matchStatus && matchPriority && matchAssignee;
    });

    // ソート適用
    applySorting();
    updateStats(filteredData);
    renderRows(filteredData);
  }

  // ソート処理
  function applySorting() {
    const sortValue = container.querySelector('#sort-select').value;

    filteredData.sort((a, b) => {
      switch(sortValue) {
        case 'created_desc':
          return new Date(b.created_at || b.作成日時 || 0) - new Date(a.created_at || a.作成日時 || 0);
        case 'created_asc':
          return new Date(a.created_at || a.作成日時 || 0) - new Date(b.created_at || b.作成日時 || 0);
        case 'name_asc':
          return (a.project_name || a.name || '').localeCompare(b.project_name || b.name || '');
        case 'priority_desc':
          const priorityOrder = { '高': 3, '中': 2, '低': 1 };
          return (priorityOrder[b.priority] || 0) - (priorityOrder[a.priority] || 0);
        case 'status_asc':
          return (a.status || '').localeCompare(b.status || '');
        default:
          return 0;
      }
    });
  }

  // CSV エクスポート
  function exportCSV() {
    const headers = ['プロジェクト名', 'ステータス', '優先度', '担当者', '進捗率', '開始日', '予定終了日', '説明'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...filteredData.map(row => [
        `"${(row.project_name || row.name || '').replace(/"/g, '""')}"`,
        `"${(row.status || '').replace(/"/g, '""')}"`,
        `"${(row.priority || '').replace(/"/g, '""')}"`,
        `"${(row.assignee || row.担当者 || '').replace(/"/g, '""')}"`,
        row.progress || row.進捗率 || 0,
        `"${(row.start_date || row.開始日 || '').replace(/"/g, '""')}"`,
        `"${(row.end_date || row.終了予定日 || '').replace(/"/g, '""')}"`,
        `"${(row.description || '').replace(/"/g, '""')}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `app_development_projects_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データの読み込みと描画
  if (tables && tables[0] && tables[0].records) {
    currentData = tables[0].records;
    filteredData = [...currentData];
    renderRows(filteredData);
    updateStats(filteredData);
  }

  // API からの最新データ取得
  if (window.aivicApi) {
    window.aivicApi.list(0).then(rows => {
      if (rows) {
        currentData = rows;
        applyFilters();
      }
    });
  }

  // 検索ボタンのイベントリスナー
  container.querySelector('#btn-search').addEventListener('click', applyFilters);

  // リセットボタンのイベントリスナー
  container.querySelector('#btn-reset').addEventListener('click', () => {
    container.querySelector('#input-search').value = '';
    container.querySelector('#status-filter').value = '';
    container.querySelector('#priority-filter').value = '';
    container.querySelector('#assignee-filter').value = '';
    applyFilters();
  });

  // ソート変更のイベントリスナー
  container.querySelector('#sort-select').addEventListener('change', () => {
    applySorting();
    renderRows(filteredData);
  });

  // CSV エクスポートボタン
  container.querySelector('#btn-csv-export').addEventListener('click', exportCSV);

  // 新規プロジェクトボタン
  container.querySelector('#btn-new-project').addEventListener('click', () => {
    window.showScreen('scr-3');
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 削除ボタン
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn) {
      if (!confirm('このプロジェクトを削除しますか？')) return;

      const id = deleteBtn.dataset.id;
      if (window.aivicApi) {
        await window.aivicApi.delete(0, id);
        const rows = await window.aivicApi.list(0);
        if (rows) {
          currentData = rows;
          applyFilters();
        }
      }
      return;
    }

    // 編集ボタン
    const editBtn = e.target.closest('.edit-btn');
    if (editBtn) {
      window.showScreen('scr-3');
      return;
    }

    // 行クリック（詳細表示）
    const row = e.target.closest('tr[data-id]');
    if (row && !e.target.closest('button')) {
      window.showScreen('scr-3');
    }
  });

  // Enterキーでの検索
  container.querySelector('#input-search').addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
      applyFilters();
    }
  });
}

function(container, apiUrl, tables) {
  let currentAppId = null;

  // アプリ一覧を描画する関数
  function renderAppList(apps) {
    const appListEl = container.querySelector('#app-list');
    appListEl.innerHTML = apps.map(app => `
      <div class="app-item p-3 mb-2 rounded cursor-pointer ${currentAppId === app.id ? 'selected' : ''}" 
           data-id="${app.id}" 
           style="background: ${currentAppId === app.id ? 'var(--primary)' : 'var(--bg-card)'}; 
                  color: ${currentAppId === app.id ? '#fff' : 'var(--text)'}; 
                  border: 1px solid rgba(255,255,255,0.08);">
        <div style="font-size: 13px; font-weight: 600; margin-bottom: 4px;">${app.name || '無題のアプリ'}</div>
        <div style="font-size: 11px; opacity: 0.8;">${getStatusLabel(app.status)} • ${app.platform || '未設定'}</div>
        <div style="font-size: 11px; opacity: 0.7; margin-top: 2px;">${app.assignee || '担当者未設定'}</div>
      </div>
    `).join('');
  }

  // ステータスラベルを取得
  function getStatusLabel(status) {
    const labels = {
      'planning': '企画中',
      'development': '開発中', 
      'testing': 'テスト中',
      'staging': 'ステージング',
      'production': '本番運用'
    };
    return labels[status] || '未設定';
  }

  // アプリ詳細を表示する関数
  function showAppDetail(app) {
    currentAppId = app.id;

    // ヘッダー更新
    container.querySelector('#app-title').textContent = app.name || '無題のアプリ';
    container.querySelector('#app-subtitle').textContent = `${getStatusLabel(app.status)} • 最終更新: ${new Date(app.updated_at || Date.now()).toLocaleDateString()}`;

    // フォーム値設定
    container.querySelector('#input-app-name').value = app.name || '';
    container.querySelector('#select-status').value = app.status || '';
    container.querySelector('#select-platform').value = app.platform || '';
    container.querySelector('#input-assignee').value = app.assignee || '';
    container.querySelector('#textarea-description').value = app.description || '';
    container.querySelector('#input-tech-stack').value = app.tech_stack || '';
    container.querySelector('#input-api-endpoint').value = app.api_endpoint || '';
    container.querySelector('#textarea-features').value = app.features || '';
    container.querySelector('#input-progress').value = app.progress || '';
    container.querySelector('#input-start-date').value = app.start_date || '';
    container.querySelector('#input-due-date').value = app.due_date || '';
    container.querySelector('#textarea-dev-notes').value = app.dev_notes || '';
    container.querySelector('#input-repo-url').value = app.repo_url || '';
    container.querySelector('#input-deploy-url').value = app.deploy_url || '';
    container.querySelector('#textarea-env-vars').value = app.env_vars || '';

    // 表示切り替え
    container.querySelector('#no-selection').style.display = 'none';
    container.querySelector('#app-detail').style.display = 'block';
    container.querySelector('#btn-save').style.display = 'block';

    // 一覧の選択状態更新
    renderAppList(tables[0].records || []);
  }

  // タブ切り替え
  function switchTab(tabId) {
    // タブボタンの状態更新
    container.querySelectorAll('.tab-btn').forEach(btn => {
      const isActive = btn.dataset.tab === tabId;
      btn.style.color = isActive ? 'var(--text)' : 'var(--text-muted)';
      btn.style.borderBottomColor = isActive ? 'var(--primary)' : 'transparent';
      btn.classList.toggle('active', isActive);
    });

    // タブコンテンツの表示切り替え
    container.querySelectorAll('.tab-content').forEach(content => {
      content.style.display = content.id === `tab-${tabId}` ? 'block' : 'none';
    });
  }

  // 初期データ読み込み
  window.aivicApi.list(0).then(apps => {
    if (apps && apps.length > 0) {
      renderAppList(apps);
    }
  });

  // アプリ選択イベント
  container.addEventListener('click', (e) => {
    const appItem = e.target.closest('.app-item');
    if (appItem) {
      const appId = appItem.dataset.id;
      const app = (tables[0].records || []).find(a => a.id == appId);
      if (app) {
        showAppDetail(app);
      }
    }
  });

  // タブ切り替えイベント
  container.addEventListener('click', (e) => {
    const tabBtn = e.target.closest('.tab-btn');
    if (tabBtn) {
      switchTab(tabBtn.dataset.tab);
    }
  });

  // 保存ボタンイベント
  container.querySelector('#btn-save').addEventListener('click', async () => {
    if (!currentAppId) return;

    const formData = {
      name: container.querySelector('#input-app-name').value,
      status: container.querySelector('#select-status').value,
      platform: container.querySelector('#select-platform').value,
      assignee: container.querySelector('#input-assignee').value,
      description: container.querySelector('#textarea-description').value,
      tech_stack: container.querySelector('#input-tech-stack').value,
      api_endpoint: container.querySelector('#input-api-endpoint').value,
      features: container.querySelector('#textarea-features').value,
      progress: container.querySelector('#input-progress').value,
      start_date: container.querySelector('#input-start-date').value,
      due_date: container.querySelector('#input-due-date').value,
      dev_notes: container.querySelector('#textarea-dev-notes').value,
      repo_url: container.querySelector('#input-repo-url').value,
      deploy_url: container.querySelector('#input-deploy-url').value,
      env_vars: container.querySelector('#textarea-env-vars').value,
      updated_at: new Date().toISOString()
    };

    const updated = await window.aivicApi.update(0, currentAppId, formData);
    if (updated) {
      // 成功時の処理
      const apps = await window.aivicApi.list(0);
      if (apps) {
        tables[0].records = apps;
        renderAppList(apps);
        const updatedApp = apps.find(a => a.id == currentAppId);
        if (updatedApp) {
          showAppDetail(updatedApp);
        }
      }
    }
  });

  // 初期状態では基本情報タブを表示
  switchTab('basic');
}
